UPDATE pln03_resrch
   SET pln03_class_tree_id     = #{req.classTreeId}
     , pln03_issuing_entity_id = #{req.issuingEntityId}
     , pln03_visit_reason      = #{req.visitReason}
     , pln03_resrch_start_date = #{req.resrchStartDate}
     , pln03_resrch_close_date = #{req.resrchCloseDate}
     , pln03_cfrm_emp_id       = #{req.cfrmPersonId}
     , pln03_note              = #{req.note}
     , pln03_target_type_code  = #{req.targetTypeCode}
 WHERE pln03_resrch_id = #{req.resrchId}
   AND pln03_reg_emp_id = #{regPersonId}
   AND pln03_cfrm_date IS NULL

UPDATE pln03_resrch
   SET pln03_close_yn   = CASE WHEN #{close} THEN 'true' ELSE 'false' END
     , pln03_close_date = CASE WHEN #{close} THEN f_trunc(f_sysdate()) ELSE NULL END
 WHERE pln03_resrch_id = #{resrchId}
   AND pln03_reg_emp_id = #{regPersonId}
   AND pln03_cfrm_date IS NULL

UPDATE pln03_resrch
   SET pln03_cfrm_emp_id = #{cfrmPersonId}
     , pln03_cfrm_date   = f_trunc(f_sysdate())
 WHERE pln03_resrch_id = #{resrchId}
   AND pln03_cfrm_emp_id = #{cfrmPersonId}
   AND pln03_close_date IS NOT NULL
   AND pln03_cfrm_date IS NULL
